from lib import *
S = SS('w58')
steps = [
    step("自连接:套接字 bind 到端口 P,再 connect 到自己的地址 127.0.0.1:P,没有监听者。按 TCP 规范,这是同时打开的特例,可以成功。在 macOS 上试了四种写法(普通 bind、加 SO_REUSEADDR、加 SO_REUSEPORT、bind 0.0.0.0 再 connect 127.0.0.1:P):connect 全部直接返回 EINVAL,同时抓包,线上一个 TCP 包都没有(0 个)——内核在 connect 里就拒绝了“源地址端口等于目的地址端口”的自连接,SYN 根本没发出去。", t=tl(S(1)), mark=lidx(S(1), 'EINVAL', '四种写法 macOS'), done=lidx(S(1), 'bind 127.0.0.1:P 再 connect 自己', '加 SO_REUSEADDR', '加 SO_REUSEPORT'), kv=KV([['四种写法', '全部 EINVAL'], ['线上 TCP 包', '0 个'], ['含义', 'macOS 在 connect 里拒绝自连接']], ['四种写法'])),
    step("同时打开本身是可以的:两个套接字各 bind 一个固定端口 A 和 B,同一时刻互相 connect。lo0 上用 netlab 加每方向 150 ms 延迟,让两个 SYN 在路上交叉。线上(去重后):+0.0 ms 两个方向各一个 SYN;+150.1 ms 两个方向各一个 SYN+ACK;+300.4 ms 两个方向各一个 ACK。中途(约 180 ms)netstat 看到两个套接字都是 SYN_RCVD(SYN_RECEIVED);两个 connect 都在 300 ms 后成功返回,连上之后 a 发的数据 b 收到 b'from a'。注意这里没有“客户端”和“服务端”之分:两边做同样的事,对称地走完三个报文来回。", t=tl(S(2)), mark=lidx(S(2), 'SYN_RCVD', '150.1 ms'), done=lidx(S(2), '+    0.0 ms', '300.4 ms', '连上之后'), kv=KV([['+0 ms', '两个 SYN 交叉'], ['+150 ms', '两个 SYN+ACK 交叉'], ['+300 ms', '两个 ACK,双方 ESTABLISHED'], ['中途状态', '两边都是 SYN_RCVD']], ['中途状态'])),
    step("重复:无额外延迟的 lo0 上 20 次、加 150 ms 延迟 20 次,两端都连上的各是 20 次 / 20 次,没有出现 ECONNREFUSED。也就是说在这台机器上,两个线程同时 connect,即使没有人为加延迟也能成功同时打开(原因没有查证,推测是两个线程的 connect 在回环上几乎同时到达)。我只测了“同时开始”的情形,没有测两边错开时间的结果,所以不能说明错开多少会失败。", t=tl(S(3)), mark=lidx(S(3), '延迟 0 ms', '延迟 150 ms'), done=lidx(S(3), '延迟 0 ms'), b=bars([['无延迟 成功', 20, '20 / 20'], ['150 ms 延迟 成功', 20, '20 / 20']], 20, mark=[], done=[0, 1]), kv=KV([['无延迟', '20 / 20 成功'], ['150 ms 延迟', '20 / 20 成功'], ['错开时间', '没有测']], ['错开时间'])),
    step("自连接本来是怎么“意外”发生的:客户端不 bind,connect 到本机一个没人监听、又落在临时端口范围(49152–65535,共 16384 个端口)里的端口,内核给客户端挑的源端口恰好等于目标端口。向端口 57343 连 60000 次:59996 次 ECONNREFUSED,4 次 EINVAL,成功(自连接)0 次;这 4 次内核挑的源端口都是 57343,正是目标端口。理论概率约 1/16384,60000 次期望 3.7 次,实测 4 次,吻合。在允许自连接的系统上,这 4 次就会变成“连上了自己”;macOS 把它们都拒绝了。", t=tl(S(4)), mark=lidx(S(4), '目标端口 57343', 'EINVAL 的那几次'), done=lidx(S(4), 'net.inet.ip.portrange.first'), b=bars([['ECONNREFUSED', 59996, '59996'], ['EINVAL(自连接被拒)', 4, '4']], 60000, mark=[1], done=[0]), kv=KV([['60000 次 connect', '59996 ECONNREFUSED / 4 EINVAL'], ['EINVAL 的源端口', '都等于目标端口 57343'], ['期望', '60000 / 16384 ≈ 3.7 次']], ['EINVAL 的源端口'])),
]
A = mkartw('w58', 58, '网络协议,TCP,同时打开,自连接,EINVAL,SYN_RCVD,真实验证,动画演示',
    '实测 TCP 同时打开与自连接:macOS 拒绝自连接(四种写法都是 EINVAL,线上 0 包);两个套接字互相 connect 在 150 ms 延迟下 SYN、SYN+ACK、ACK 各双向一个,中途都是 SYN_RCVD;向临时端口连 60000 次,4 次因源端口等于目标端口被 EINVAL 拒绝。',
    'TCP 握手不一定是“一个主动、一个被动”。两端同时 connect 对方,会走一条对称的路径;极端情形下,连自己都能连上。这篇把这两种少见的情形在 macOS 上实际跑一遍,看线上长什么样、内核怎么处理。',
    [('4 / 60000', '向临时端口连 60000 次,内核挑到源端口等于目标端口、被 EINVAL 拒绝的次数'), ('0 个包', '自连接 connect 返回 EINVAL 时线上的 TCP 包数'), ('20 / 20', '两个套接字互相 connect 同时打开成功的次数(有无 150 ms 延迟都是)')],
    [('自连接被拒', '<p>规范允许“连自己”,macOS 在 connect 里直接返回 EINVAL,线上一个包也没有。</p>'),
     ('同时打开的线上形态', '<p>两个 SYN 交叉,两个 SYN+ACK 交叉,两个 ACK;中途两边都是 SYN_RCVD,没有谁是客户端谁是服务端。</p>'),
     ('成功率', '<p>在回环上 20 次全部成功,有无延迟都一样;错开时间的情形没有测。</p>'),
     ('意外的自连接', '<p>临时端口范围内随机挑到与目标相同的概率约 1/16384;实测 60000 次里 4 次被内核拒绝。</p>')],
    steps,
    [ENV_W + '。第一、四节在 lo0 上;第二节用 netlab 加每方向 150 ms 延迟,抓包经过去重(dummynet 会让同一个包被抓多次);第三节只测了两个线程同时开始 connect 的情形',
     '没有验证:允许自连接的系统(Linux)上的实际行为;两个 connect 错开时间后同时打开失败的边界;同时打开时的序号细节(只看了标志位);netstat 里除 SYN_RCVD 之外的其它中间状态(只取了一个时间点);自连接在应用层造成问题的例子'],
    '同时打开与自连接')
